public class ControllerV4HandlerAdapter implements MyHandlerAdapter {

    @Override
    public boolean supports(Object handler) {
        return (handler instanceof ControllerV4);
    }

    @Override
    public ModelView handle(HttpServletRequest request,
                          HttpServletResponse response,
                          Object handler) {

        ControllerV4 controller = (ControllerV4) handler;

        Map<String, String> paramMap = createParamMap(request);
        Map<String, Object> model = new HashMap<>();      // 어댑터가 만든다

        String viewName = controller.process(paramMap, model);

        // 형식을 맞춘다 — String 을 ModelView 로
        ModelView mv = new ModelView(viewName);
        mv.setModel(model);
        return mv;
    }
}

private void initHandlerAdapters() {
    handlerAdapters.add(new ControllerV3HandlerAdapter());
    handlerAdapters.add(new ControllerV4HandlerAdapter());   // 이 한 줄
}

private void initHandlerMappingMap() {
    // v3 컨트롤러
    handlerMappingMap.put("/front-controller/v5/v3/members/new-form",
                          new MemberFormControllerV3());
    // v4 컨트롤러
    handlerMappingMap.put("/front-controller/v5/v4/members/new-form",
                          new MemberFormControllerV4());
}
